import * as React from "react";
import { Box, Typography } from "@mui/material";

export default function PlannerPage() {
  const days = [
    { day: "MON", text: "Available from 9 AM - 5 PM" },
    { day: "TUE", text: "Available from 10 AM - 4 PM" },
    { day: "WED", text: "Fully booked" },
    { day: "THU", text: "Available from 12 PM - 6 PM" },
    { day: "FRI", text: "Available from 9 AM - 3 PM" },
  ];

  return (
    <Box
      sx={{
        width: "100%",
        minHeight: "100vh",
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center", // Centers content vertically
        padding: { xs: 2, sm: 4 },
        position: "relative",
        overflow: "hidden", // Prevents content from overflowing
      }}
    >
      {/* Fullscreen Background Image */}
      <Box
        sx={{
          position: "fixed",
          top: 0,
          left: 0,
          width: "100vw",
          height: "100vh",
          backgroundImage: "url('/Background15.jpg')",
          backgroundSize: "cover",
          backgroundPosition: "center",
          backgroundAttachment: "fixed",
          zIndex: -1,
        }}
      />

      {/* Centered Content */}
      <Box
        sx={{
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          textAlign: "center",
        }}
      >
        <Typography
          variant="h3"
          sx={{
            fontFamily: "'Playfair Display', serif",
            fontWeight: 700,
            marginBottom: { xs: 2, sm: 3 },
            fontSize: { xs: "1.8rem", sm: "2.5rem" },
            color: "#6B4F4F",
          }}
        >
          Available Planner Services
        </Typography>
        <Typography
          variant="subtitle1"
          sx={{
            fontFamily: "'Playfair Display', serif",
            marginBottom: { xs: 3, sm: 4 },
            fontSize: { xs: "1rem", sm: "1.2rem" },
            color: "#6B4F4F",
          }}
        >
          Book Now
        </Typography>

        {/* Day Buttons */}
        {days.map((item, index) => (
          <Box
            key={index}
            sx={{
              width: "100px", // Button size
              height: "50px",
              backgroundColor: "#BBAFA2",
              color: "white",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              borderRadius: 4,
              fontWeight: "bold",
              textAlign: "center",
              marginBottom: 2,
              cursor: "pointer",
              boxShadow: "0 2px 4px rgba(0, 0, 0, 0.2)", // Button shadow effect
              transition: "0.3s",
              "&:hover": {
                backgroundColor: "#A89C8C",
              },
            }}
          >
            <Typography
              variant="h6"
              sx={{
                fontFamily: "'Roboto', sans-serif",
                fontWeight: 700,
                fontSize: { xs: "1rem", sm: "1.2rem" },
              }}
            >
              {item.day}
            </Typography>
          </Box>
        ))}
      </Box>
    </Box>
  );
}
